    {
        private const float ScaleDuration = 0.5f;

        private readonly IEnumerable<IUnityItem> _items;

        public ItemsShowJob(IEnumerable<IUnityItem> items, int executionOrder = 0) : base(executionOrder)
        {
            _items = items;
        }

